PREFIX : <https://w3id.org/rastro/energia#>
SELECT (SUM(?o * ?p / 100) AS ?total) WHERE {
  { SELECT ?c (SUM(?oil) AS ?o) WHERE {
      ?wp a :WellProduction ; :inConcession ?c ; :oil ?oil .
    } GROUP BY ?c }
  { SELECT ?c (SUM(?pct) AS ?p) WHERE {
      ?s a :Stake ; :inConcession ?c ; :partner ?e ; :percent ?pct .
      FILTER EXISTS { ?e :name ?n . FILTER(UCASE(STR(?n)) = "YPF" || STRSTARTS(UCASE(STR(?n)), "YPF S.A")) }
    } GROUP BY ?c }
}
